// World-Class QA (2026-08-07): real-data cutover. Gated by env, not a
// hardcoded disable, so CI / fresh deployments (no LDI_SIMULATOR_ENABLED
// set) keep generating mock data by default -- only this specific
// environment's local .env (gitignored, never committed) turns it off.
if (env.get('LDI_SIMULATOR_ENABLED') === 'false') {
    node.status({ fill: 'grey', shape: 'ring', text: 'disabled (real-data mode)' });
    return null;
}


// ══════════════════════════════════════════════════════════════════
// LDI ALARM SIMULATOR — noise codes (real distribution, uncorrelated
// equipment/calibration faults) + condition-driven codes (fired only
// when the matching telemetry parameter is actually out of spec right
// now, per the same thresholds v_ldi_alarm_context/migration 054+057
// uses) + a rare genuine-Critical branch.
//
// LDI Alarm Fidelity Audit (docs/audit/LDI_ALARM_FIDELITY_AUDIT.md,
// 2026-08-11) findings addressed here:
//  - #6 burst/flood: a debounce cooldown (public.ldi_alarm_state) now
//    suppresses re-firing the same (machine, code) within COOLDOWN_MIN
//    minutes, so a sustained fault reads as a handful of alarms while
//    active, not hundreds of near-duplicate rows every 10-40s.
//  - #7 correlation semantics: every inserted row now carries an explicit
//    link_basis ('causal' for condition-driven/critical codes whose
//    related_log_id is the actual triggering telemetry row, 'nearest' for
//    background noise codes with no designed relationship) instead of
//    relying on migration 051's trigger to silently backfill both cases
//    identically.
//  - #8 severity distribution: RARE_CRITICAL adds real Critical-severity
//    vendor codes (migration 036) at a low, independent probability so the
//    top of the severity taxonomy is actually reachable under normal
//    simulation, not just theoretically defined.
// ══════════════════════════════════════════════════════════════════
const pool = global.get('pgPool');
if (!pool) { node.status({ fill: 'red', shape: 'ring', text: 'no pgPool' }); return null; }

// codes with no known telemetry correlation - unconditioned background
// noise. World-Class QA (2026-08-07): replaced with real codes from the
// vendor Alarm Master import (migration 061) -- 91012/91017/91020/91024/
// 93007/91029/97014/20/20021/2 never existed in the real 1,820-code list
// (invented for early prototyping); swapped 1:1 for real generic-fault
// codes (camera/PLC/comms/network/DB), keeping the exact same weights.
// 90013 (5th ALIGN_CODES entry) also didn't exist in the real list --
// dropped rather than force-substituted, since 4 real alignment codes
// already cover the category.
const NOISE_CUM = [["93004", 24.5], ["01060009", 31.3], ["0106000C", 38.2],
    ["0106001C", 45.0], ["01060013", 51.8], ["01100001", 58.7], ["01130002", 65.5], ["010E0064", 72.4],
    ["10006", 79.2], ["92013", 86.0], ["97005", 92.9], ["80001", 100.0]];
const MACHINES = [["LDI-01", 16.6], ["LDI-02", 33.2], ["LDI-03", 44.1], ["LDI-04", 55.0],
    ["LDI-05", 72.2], ["LDI-06", 89.3], ["LDI-07", 93.0], ["LDI-08", 96.7],
    ["LDI-09", 98.4], ["LDI-10", 100.0]];
// alignment codes correlated to PE/JE out-of-tolerance (misalignment <-> PE error)
const ALIGN_CODES = ["90001", "90004", "90005", "90012"];
// LDI Alarm Fidelity Audit fix #8: 2 real Critical-severity vendor codes
// (migration 036), fired independently of the noise/condition pools at a
// rate calibrated for roughly 1 event per machine per 1-2 days.
const RARE_CRITICAL_CODES = ["01180016", "0C020014"]; // Emergency Stop / Safety sensor triggered
const RARE_CRITICAL_PROB = 0.00002; // per machine per 10s tick
const RATE_PER_TICK = 0.01194 * 20 * (15 / 20); // unchanged overall pacing, noise share only
const COOLDOWN_MIN = 12; // debounce window: suppress re-fire of the same (machine, code) within this many minutes

function pick(table) {
    const x = Math.random() * 100;
    for (const [v, c] of table) if (x <= c) return v;
    return table[table.length - 1][0];
}
function poissonCount(rate) {
    let n = 0, L = Math.exp(-rate), p = 1;
    do { p *= Math.random(); n++; } while (p > L);
    return n - 1;
}
// relatedLogId: the literal ldi_data.log_id of the telemetry row that
// triggered this alarm, when known (condition-driven/critical codes only --
// noise codes aren't tied to any specific board, so they pass null and let
// migration 051's trigger fall back to its nearest-match heuristic).
// linkBasis records which case this is explicitly, rather than leaving it
// to be inferred from whether related_log_id happens to be null.
function newRow(eq, code, ts, relatedLogId, linkBasis) {
    return {
        logid: 'SIM-ALM-' + ts.getTime() + '-' + eq + '-' + code + '-' + Math.floor(Math.random() * 1e6),
        logdate: ts.toISOString(),
        errorcode: code,
        errortime: ts.toISOString().replace('T', ' ').substring(0, 19),
        equipmentid: eq,
        factory: Math.random() < 0.75 ? '2' : '3',
        process: ['DF INNER', 'DF OUTER', 'SM'][Math.floor(Math.random() * 3)],
        related_log_id: relatedLogId || null,
        link_basis: linkBasis
    };
}

const now = Date.now();

function generate(cooldownSet) {
    const rows = [];
    const debounced = (eq, code) => cooldownSet.has(eq + '|' + code);

    // ── background noise (unconditioned, real historical distribution) ──
    const nNoise = poissonCount(RATE_PER_TICK);
    for (let k = 0; k < nNoise; k++) {
        const eq = pick(MACHINES), code = pick(NOISE_CUM);
        if (debounced(eq, code)) continue;
        rows.push(newRow(eq, code, new Date(now - Math.floor(Math.random() * 9000)), null, 'nearest'));
    }

    // ── rare genuine-Critical events, independent of telemetry state ──
    for (const [eq] of MACHINES) {
        if (Math.random() < RARE_CRITICAL_PROB) {
            const code = RARE_CRITICAL_CODES[Math.floor(Math.random() * RARE_CRITICAL_CODES.length)];
            if (!debounced(eq, code)) rows.push(newRow(eq, code, new Date(now), null, 'nearest'));
        }
    }

    // ── condition-driven alarms: only fire when telemetry is actually out of
    //    spec right now, using the same thresholds as v_ldi_alarm_context ──
    const sql = `
        SELECT DISTINCT ON (eqp_id) eqp_id, process, temperature, humidity,
               pe_1, je_1, scan_speed, air_vacuum, log_id
        FROM public.ldi_data
        WHERE time > NOW() - INTERVAL '3 minutes'
        ORDER BY eqp_id, time DESC`;

    return new Promise((resolve) => {
        pool.query(sql, [], function (err, result) {
            if (err) { node.error('Alarm sim telemetry query failed: ' + err.message); resolve(rows); return; }
            const ts = new Date();
            // ~25%/tick per condition so a persistently out-of-spec machine
            // doesn't fire on literally every 10s tick while the fault holds
            // (debounce below is the primary flood guard; this stays as a
            // secondary pacing throttle).
            const fires = () => Math.random() < 0.25;
            for (const r of (result.rows || [])) {
                if ((r.temperature < 20 || r.temperature > 24 || r.humidity < 50 || r.humidity > 60) && fires()) {
                    if (!debounced(r.eqp_id, '91008')) rows.push(newRow(r.eqp_id, '91008', ts, r.log_id, 'causal'));
                }
                if ((Math.abs(r.pe_1) > 10 || Math.abs(r.je_1) > 10) && fires()) {
                    const code = ALIGN_CODES[Math.floor(Math.random() * ALIGN_CODES.length)];
                    if (!debounced(r.eqp_id, code)) rows.push(newRow(r.eqp_id, code, ts, r.log_id, 'causal'));
                }
                if ((r.scan_speed > 450 || r.scan_speed <= 0) && fires()) {
                    if (!debounced(r.eqp_id, '70004')) rows.push(newRow(r.eqp_id, '70004', ts, r.log_id, 'causal'));
                }
                if (r.air_vacuum !== null && (r.air_vacuum > -8 || r.air_vacuum < -30) && fires()) {
                    if (!debounced(r.eqp_id, '91009')) rows.push(newRow(r.eqp_id, '91009', ts, r.log_id, 'causal'));
                }
            }
            resolve(rows);
        });
    });
}

// debounce lookup: which (machine, code) pairs are still within cooldown
pool.query(
    `SELECT equipmentid, errorcode FROM public.ldi_alarm_state WHERE last_fired > NOW() - INTERVAL '${COOLDOWN_MIN} minutes'`,
    [],
    function (err, result) {
        if (err) { node.error('Alarm sim debounce query failed: ' + err.message); return; }
        const cooldownSet = new Set((result.rows || []).map(r => r.equipmentid + '|' + r.errorcode));
        generate(cooldownSet).then(rows => {
            if (rows.length === 0) { node.status({ fill: 'grey', shape: 'ring', text: 'no alarm' }); return; }
            node.status({ fill: 'yellow', shape: 'dot',
                text: rows.length + ' alarm: ' + rows.map(r => r.errorcode).join(',') });
            node.send({ payload: rows });
        });
    }
);
return null;

const pool = global.get('pgPool');
const rows = msg.payload || [];
if (!pool || rows.length === 0) return null;
const cols = ['logid','logdate','errorcode','errortime','equipmentid','factory','process','related_log_id','link_basis'];
const ph = rows.map((_, i) => '(' + cols.map((_, j) => '$' + (i * cols.length + j + 1)).join(',') + ')').join(',');
const params = [];
for (const r of rows) for (const c of cols) params.push(r[c]);
// ingest_ts set explicitly (not a DB default -- ldi_alarm_log is a
// compressed hypertable, see migration 081's comment on why).
const sql = 'INSERT INTO public.ldi_alarm_log (' + cols.join(',') + ',ingest_ts) VALUES ' +
    rows.map((_, i) => '(' + cols.map((_, j) => '$' + (i * cols.length + j + 1)).join(',') + ',clock_timestamp())').join(',') +
    ' ON CONFLICT (logdate, logid) DO NOTHING';

const earliestSourceTs = rows.reduce((min, r) => (r.errortime < min ? r.errortime : min), rows[0].errortime);
const nodeRef = node;

// Stage BEFORE attempting the real insert -- durable write-ahead copy,
// same pattern as ldi_auth_check (migration 081). A crash between here
// and the real INSERT's commit leaves this batch recoverable instead of
// silently gone (previously: any error here just logged and dropped it).
pool.query(
    `INSERT INTO public.ingest_staging (target_table, payload, source_ts) VALUES ($1, $2, $3) RETURNING id`,
    ['ldi_alarm_log', JSON.stringify(rows), earliestSourceTs],
    function (stageErr, stageResult) {
        if (stageErr) {
            nodeRef.error('Alarm sim staging INSERT failed: ' + stageErr.message);
            return;
        }
        const stagingId = stageResult.rows[0].id;
        pool.query(sql, params, function (err) {
            if (err) {
                nodeRef.error('Alarm sim INSERT failed: ' + err.message);
                pool.query(
                    `UPDATE public.ingest_staging SET attempts = attempts + 1, last_error = $2 WHERE id = $1`,
                    [stagingId, String(err.message).slice(0, 500)],
                    () => {}
                );
                return;
            }
            pool.query(`DELETE FROM public.ingest_staging WHERE id = $1`, [stagingId], () => {});
            nodeRef.log('Alarm sim: inserted ' + rows.length);

            // LDI Alarm Fidelity Audit fix #6 (burst/flood): record/refresh debounce
            // state for every (machine, code) that fired this tick, so almsim_gen's
            // cooldown lookup on the next tick knows to suppress a re-fire.
            const pairs = [...new Set(rows.map(r => r.equipmentid + '|' + r.errorcode))]
                .map(k => k.split('|'));
            if (pairs.length === 0) return;
            const stateCols = ['equipmentid', 'errorcode'];
            const stateVals = [];
            const statePh = pairs.map((p, i) => { stateVals.push(p[0], p[1]); return '($' + (i*2+1) + ',$' + (i*2+2) + ',NOW(),NOW(),1)'; }).join(',');
            const stateSql = 'INSERT INTO public.ldi_alarm_state (equipmentid, errorcode, first_fired, last_fired, fire_count) VALUES ' +
                statePh +
                ' ON CONFLICT (equipmentid, errorcode) DO UPDATE SET last_fired = EXCLUDED.last_fired, fire_count = ldi_alarm_state.fire_count + 1';
            pool.query(stateSql, stateVals, function (err2) {
                if (err2) nodeRef.error('Alarm sim debounce state upsert failed: ' + err2.message);
            });
        });
    }
);
return null;
